package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class ConversationContinuation {
 static JSONArray ledger(Context c)throws Exception{return new JSONArray(c.getSharedPreferences("loki_web_console",0).getString("outbox","[]"));}
 static JSONObject stop(Context c,String key)throws Exception{synchronized(LokiWebConsole.class){if(!TrackedWebRequest.validId(key))throw new IOException("依頼を確認してください");JSONArray all=ledger(c);for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);if(!key.equals(row.optString("key")))continue;if(!row.optBoolean("tracked"))throw new IOException("対象外です");if(row.optString("requestState").equals("STOPPED"))return new JSONObject().put("stopped",true).put("duplicate",true);if(!row.optString("requestState").matches("RECEIVED|RUNNING"))throw new IOException("処理開始前または完了済みです。最新の状態を確認してください");if(row.has("stopRejectedAt"))throw new IOException("この処理は個別中止に対応していません。結果を確認してください");boolean duplicate=row.has("stopRequestedAt");if(!duplicate)row.put("stopRequestedAt",System.currentTimeMillis());if(!c.getSharedPreferences("loki_web_console",0).edit().putString("outbox",all.toString()).commit())throw new IOException("中止要求を保存できません");return new JSONObject().put("stopRequested",true).put("duplicate",duplicate).put("stopped",false);}throw new IOException("依頼がありません");}}
 static JSONObject timing(JSONArray all,long now)throws Exception{ArrayList<JSONObject> samples=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject row=all.optJSONObject(i);if(row==null||!row.optBoolean("tracked")||!row.optString("requestState").equals("ANSWERED"))continue;long from=row.optLong("time"),until=row.optLong("finishedAt"),duration=until-from;if(from>0&&until>=from&&until<=now&&now-until<=604800000L&&duration<=86400000L)samples.add(row);}samples.sort((a,b)->Long.compare(b.optLong("finishedAt"),a.optLong("finishedAt")));ArrayList<Long> recent=new ArrayList<>(),previous=new ArrayList<>();for(int i=0;i<Math.min(40,samples.size());i++)(i<20?recent:previous).add(samples.get(i).getLong("finishedAt")-samples.get(i).getLong("time"));JSONObject out=new JSONObject().put("samples",recent.size()).put("scope","直近7日・最大20件の、受付後24時間以内に正常完了した記録。スマホ受付から結果通知まで。完了予測ではありません");if(!recent.isEmpty()){Collections.sort(recent);out.put("medianMs",median(recent)).put("p90Ms",recent.get(Math.max(0,(int)Math.ceil(recent.size()*.9)-1))).put("minMs",recent.get(0)).put("maxMs",recent.get(recent.size()-1));}if(previous.size()==20){Collections.sort(previous);out.put("previousMedianMs",median(previous));}return out;}
 static long median(ArrayList<Long> a){return a.size()%2==1?a.get(a.size()/2):(a.get(a.size()/2-1)+a.get(a.size()/2))/2;}
 static JSONObject status(MainActivity owner)throws Exception{JSONArray all=ledger(owner),rows=new JSONArray();for(int i=0;i<all.length();i++){JSONObject v=all.getJSONObject(i),row=new JSONObject();for(String key:new String[]{"key","tracked","requestState","time","receivedAt","startedAt","finishedAt","stopRequestedAt","stopRejectedAt"})if(v.has(key))row.put(key,v.get(key));rows.put(row);}return new JSONObject().put("requests",rows).put("runtime",owner.webConversationRuntime()).put("partials",ConversationReliability.partials(all,System.currentTimeMillis())).put("timing",timing(all,System.currentTimeMillis()));}
 static JSONObject merge(Context c,JSONObject input)throws Exception{synchronized(LokiWebConsole.class){synchronized(MainActivity.class){JSONArray keys=input.getJSONArray("keys");String operation=input.getString("changeId"),text=input.getString("message").trim();if(keys.length()<2||keys.length()>10||!operation.matches("[a-zA-Z0-9-]{8,80}"))throw new IOException("2〜10件を選んでください");Set<String> selected=new LinkedHashSet<>();for(int i=0;i<keys.length();i++){String key=keys.getString(i);if(!TrackedWebRequest.validId(key)||!selected.add(key))throw new IOException("選択IDが不正です");}ArrayList<String> sorted=new ArrayList<>(selected);Collections.sort(sorted);String newKey=RecorderPhotoStore.hash((String.join(":",sorted)+":"+operation).getBytes("UTF-8"));JSONArray all=ledger(c);JSONObject existing=null;for(int i=0;i<all.length();i++)if(newKey.equals(all.getJSONObject(i).optString("key")))existing=all.getJSONObject(i);if(existing!=null){if(!existing.optString("message").equals(text))throw new IOException("同じ操作IDの本文が変わりました");return new JSONObject().put("queued",existing.optBoolean("accepted")).put("tracked",true).put("requestKey",newKey).put("duplicate",true);}
 ArrayList<JSONObject> originals=new ArrayList<>();String reference=null;for(String key:selected){JSONObject found=null;for(int i=0;i<all.length();i++)if(key.equals(all.getJSONObject(i).optString("key")))found=all.getJSONObject(i);if(found==null||!found.optBoolean("tracked")||!found.optString("requestState").equals("QUEUED")||!MainActivity.hasQueuedWebCommand(c,key))throw new IOException("選んだ質問が受信・変更されました。まとめ直してください");String ref=found.optString("referenceKey");if(reference==null)reference=ref;else if(!reference.equals(ref))throw new IOException("異なる画像参照の質問はまとめられません");originals.add(found);}
 String wire=TrackedWebRequest.wire(newKey,text,reference);ConversationRecoveryStore.save(c,newKey,"send",new JSONObject().put("requestId",operation).put("message",text).put("referenceKey",reference));for(JSONObject old:originals)old.put("requestState","SUPERSEDED").put("replacementKey",newKey).put("receiptAt",System.currentTimeMillis());JSONObject row=new JSONObject().put("key",newKey).put("time",System.currentTimeMillis()).put("message",text).put("referenceKey",reference).put("device",originals.get(0).optString("device")).put("tracked",true).put("requestState","CREATED");JSONArray updated=WebRequestLedger.append(all,row);if(updated==null)throw new IOException("送信記録がいっぱいです");SharedPreferences prefs=c.getSharedPreferences("loki_web_console",0);if(!prefs.edit().putString("outbox",updated.toString()).commit())throw new IOException("統合を保存できません");boolean queued=MainActivity.mergeQueuedWebCommands(c,selected,wire);row.put("accepted",queued).put("requestState",queued?"QUEUED":"FAILED");if(!prefs.edit().putString("outbox",updated.toString()).commit()||!queued)throw new IOException("元の質問は差し替え済みですが統合結果は未確認です。自動再送していません");return new JSONObject().put("queued",true).put("tracked",true).put("requestKey",newKey);}}}
 private ConversationContinuation(){}
}
